), source_check AS MATERIALIZED (
SELECT bool_and(e.metadata IS NOT DISTINCT FROM (
 SELECT jsonb_build_array(encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),pg_get_userbyid(p.proowner),p.proacl::text,p.proconfig,p.provolatile,p.prosecdef,p.proleakproof,p.proisstrict,p.proretset,l.lanname)
 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(e.signature))) AS exact FROM expected e
)
SELECT ordinal,check_name,passed FROM (VALUES
(1,'read_only',(current_setting('transaction_read_only')='on')),
(2,'114482_recorded',(EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260811448200'))),
(3,'114483_absent',(to_regnamespace('hotels_read_once_private') IS NULL AND NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version ~ '^20260811[0-9]{6}$' AND version>'20260811448200'))),
(4,'predecessor_sources_security',((SELECT exact FROM source_check))),
(5,'successor_complete',(hotels_shadow_successor_private.state('9b6d99a0-923a-4fbc-be54-c066e856e6ca')->>'status'='SUCCESSOR_ALREADY_COMPLETE')),
(6,'flags_exact',(hotels_lifecycle_private.safe_state()->'feature_flags' = '{"hotel_rooms_v2_enabled":false,"hotel_external_sync_enabled":true,"hotel_instant_booking_enabled":false,"hotel_stripe_connect_enabled":false}'::jsonb)),
(7,'public_booking_off',(hotels_lifecycle_private.public_booking_enabled() IS FALSE)),
(8,'payment_lineage',(public.hotel_v2_seven_arches_payment_policy_lineage_is_exact() IS TRUE)),
(9,'commission_eur10',((SELECT count(*)=1 FROM public.hotel_commission_policies WHERE hotel_id='9b6d99a0-923a-4fbc-be54-c066e856e6ca' AND commission_mode='per_allocated_room_per_night' AND amount=10 AND currency='EUR' AND is_active AND review_status='reviewed')))) gates(ordinal,check_name,passed) ORDER BY ordinal;
ROLLBACK;
